{
  "fields": [
    {
      "apiName": "mast_standard_pole",
      "label": "Type of Pole - Standard",
      "type": "picklist",
      "required": true,
      "options": [
        "Standard Lighting Pole",
        "Custom Lighting Pole",
        "Mid Hinge Pole"
      ],
      "controllingField": "type_of_mast",
      "controllingValues": [
        "Octagonal Pole"
      ]
    },
    {
      "apiName": "standard_op_folder_std",
      "labelFormat": "Weight Estimator - {value}",
      "type": "folder",
      "iconColor": "red",
      "controllingField": "mast_standard_pole",
      "controllingValues": [
        "Standard Lighting Pole"
      ],
      "modalConfigsByValue": {
        "Standard Lighting Pole": {
          "title": "WEIGHT ESTIMATOR - STANDARD LIGHTNING POLE",
          "modalFields": [
            {
              "id": "op_general_details",
              "label": "General Details - Segments",
              "expanded": true,
              "fields": [
                {
                  "apiName": "s1_no_of_items",
                  "label": "No. of Items (Segment 1)",
                  "type": "number",
                  "colSpan": 4,
                  "defaultValue": 1,
                  "max": 10
                },
                {
                  "apiName": "s2_no_of_items",
                  "label": "No. of Items (Segment 2)",
                  "type": "number",
                  "colSpan": 4,
                  "max": 10
                },
                {
                  "apiName": "op_wind_speed",
                  "label": "Wind Speed ?",
                  "type": "picklist",
                  "options": [
                    "YES",
                    "NO"
                  ],
                  "defaultValue": "NO",
                  "colSpan": 2
                },
                {
                  "apiName": "op_wind_speed_value",
                  "label": "Value",
                  "type": "text",
                  "controllingField": "op_wind_speed",
                  "controllingValues": [
                    "YES"
                  ],
                  "colSpan": 2
                }
              ]
            },
            {
              "id": "segment_1_pole_details",
              "label": "Segment - 1 Pole Details",
              "expanded": true,
              "controllingField": "s1_no_of_items",
              "controllingValues": [
                ">=1"
              ],
              "cloneFrom": "op_s1_pole"
            },
            {
              "id": "segment_1_foundation",
              "label": "Foundation accessories - 1",
              "expanded": false,
              "controllingField": "s1_no_of_items",
              "controllingValues": [
                ">=1"
              ],
              "cloneFrom": "op_s1_foundation"
            },
            {
              "id": "segment_1_bracket",
              "label": "Bracket Details - 1",
              "expanded": false,
              "controllingField": "s1_no_of_items",
              "controllingValues": [
                ">=1"
              ],
              "cloneFrom": "op_s1_bracket"
            },
            {
              "id": "segment_2_pole_details",
              "label": "Segment - 2 Pole Details",
              "expanded": false,
              "controllingField": "s2_no_of_items",
              "controllingValues": [
                ">=1"
              ],
              "cloneFrom": "op_s2_pole"
            },
            {
              "id": "segment_2_foundation",
              "label": "Foundation accessories - 2",
              "expanded": false,
              "controllingField": "s2_no_of_items",
              "controllingValues": [
                ">=1"
              ],
              "cloneFrom": "op_s2_foundation"
            },
            {
              "id": "segment_2_bracket",
              "label": "Bracket Details - 2",
              "expanded": false,
              "controllingField": "s2_no_of_items",
              "controllingValues": [
                ">=1"
              ],
              "cloneFrom": "op_s2_bracket"
            }
          ]
        }
      }
    },
    {
      "apiName": "standard_op_folder_custom",
      "labelFormat": "Weight Estimator - {value}",
      "type": "folder",
      "iconColor": "red",
      "controllingField": "mast_standard_pole",
      "controllingValues": [
        "Custom Lighting Pole"
      ],
      "modalConfigsByValue": {
        "Custom Lighting Pole": {
          "title": "WEIGHT ESTIMATOR - CUSTOM LIGHTNING POLE",
