                  "colSpan": 2
                },
                {
                  "apiName": "for_cus_op_wind_speed_value",
                  "label": "Value",
                  "type": "text",
                  "controllingField": "for_cus_op_wind_speed",
                  "controllingValues": [
                    "YES"
                  ],
                  "colSpan": 2
                }
              ]
            },
            {
              "id": "segment_1_pole_details_for_cus_op",
              "label": "Segment - 1 Pole Details",
              "expanded": true,
              "controllingField": "s1_no_of_items_for_cus_op",
              "controllingValues": [
                ">=1"
              ],
              "cloneFrom": "cus_op_s1_pole"
            },
            {
              "id": "segment_1_foundation_for_cus_op",
              "label": "Foundation accessories - 1",
              "expanded": false,
              "controllingField": "s1_no_of_items_for_cus_op",
              "controllingValues": [
                ">=1"
              ],
              "cloneFrom": "cus_op_s1_foundation"
            },
            {
              "id": "segment_1_bracket_for_cus_op",
              "label": "Bracket Details - 1",
              "expanded": false,
              "controllingField": "s1_no_of_items_for_cus_op",
              "controllingValues": [
                ">=1"
              ],
              "cloneFrom": "cus_op_s1_bracket"
            },
            {
              "id": "segment_2_pole_details_for_cus_op",
              "label": "Segment - 2 Pole Details",
              "expanded": false,
              "controllingField": "s2_no_of_items_for_cus_op",
              "controllingValues": [
                ">=1"
              ],
              "cloneFrom": "cus_op_s2_pole"
            },
            {
              "id": "segment_2_foundation_for_cus_op",
              "label": "Foundation accessories - 2",
              "expanded": false,
              "controllingField": "s2_no_of_items_for_cus_op",
              "controllingValues": [
                ">=1"
              ],
              "cloneFrom": "cus_op_s2_foundation"
            },
            {
              "id": "segment_2_bracket_for_cus_op",
              "label": "Bracket Details - 2",
              "expanded": false,
              "controllingField": "s2_no_of_items_for_cus_op",
              "controllingValues": [
                ">=1"
              ],
              "cloneFrom": "cus_op_s2_bracket"
            }
          ]
        }
      }
    },
    {
      "apiName": "standard_op_folder_mid_hinge",
      "labelFormat": "Weight Estimator - {value}",
      "type": "folder",
      "iconColor": "blue",
      "controllingField": "mast_standard_pole",
      "controllingValues": [
        "Mid Hinge Pole"
      ],
      "modalConfigsByValue": {
        "Mid Hinge Pole": {
          "title": "WEIGHT ESTIMATOR - MID HINGE POLE",
          "modalFields": [
            {
              "id": "mhp_general_details",
              "label": "General Details - Mid Hinge Pole",
              "expanded": true,
              "fields": [
                {
                  "apiName": "mhp_no_of_items",
                  "label": "No. of Items",
                  "type": "number",
                  "colSpan": 4,
                  "defaultValue": 1,
                  "max": 10
                },
                {
                  "apiName": "op_mhp_wind_speed",
                  "label": "Wind Speed ?",
                  "type": "picklist",
                  "options": [
                    "YES",
                    "NO"
                  ],
                  "defaultValue": "NO",
                  "colSpan": 2
                },
                {
                  "apiName": "op_mhp_wind_speed_value",
                  "label": "Value",
                  "type": "text",
                  "controllingField": "op_mhp_wind_speed",
                  "controllingValues": [
