            {
              "id": "mhp_foundation",
              "label": "Foundation Accessories",
              "expanded": false,
              "controllingField": "mhp_no_of_items",
              "controllingValues": [
                ">=1"
              ],
              "cloneFrom": "op_mhp_foundation"
            },
            {
              "id": "mhp_bracket",
              "label": "Arm / Bracket Details",
              "expanded": false,
              "controllingField": "mhp_no_of_items",
              "controllingValues": [
                ">=1"
              ],
              "cloneFrom": "op_mhp_bracket"
            },
            {"id": "mhp_acc_section_1",  "label": "Accessories Item - 1",  "expanded": true,  "controllingField": "mhp_no_of_items", "controllingValues": [">=1"],  "cloneFrom": "mhp_accessories", "replaceTarget": "mhp_acc_", "replaceWith": "c1_mhp_acc_"},
{"id": "mhp_acc_section_2",  "label": "Accessories Item - 2",  "expanded": false, "controllingField": "mhp_no_of_items", "controllingValues": [">=2"],  "cloneFrom": "mhp_accessories", "replaceTarget": "mhp_acc_", "replaceWith": "c2_mhp_acc_"},
{"id": "mhp_acc_section_3",  "label": "Accessories Item - 3",  "expanded": false, "controllingField": "mhp_no_of_items", "controllingValues": [">=3"],  "cloneFrom": "mhp_accessories", "replaceTarget": "mhp_acc_", "replaceWith": "c3_mhp_acc_"},
{"id": "mhp_acc_section_4",  "label": "Accessories Item - 4",  "expanded": false, "controllingField": "mhp_no_of_items", "controllingValues": [">=4"],  "cloneFrom": "mhp_accessories", "replaceTarget": "mhp_acc_", "replaceWith": "c4_mhp_acc_"},
{"id": "mhp_acc_section_5",  "label": "Accessories Item - 5",  "expanded": false, "controllingField": "mhp_no_of_items", "controllingValues": [">=5"],  "cloneFrom": "mhp_accessories", "replaceTarget": "mhp_acc_", "replaceWith": "c5_mhp_acc_"},
{"id": "mhp_acc_section_6",  "label": "Accessories Item - 6",  "expanded": false, "controllingField": "mhp_no_of_items", "controllingValues": [">=6"],  "cloneFrom": "mhp_accessories", "replaceTarget": "mhp_acc_", "replaceWith": "c6_mhp_acc_"},
{"id": "mhp_acc_section_7",  "label": "Accessories Item - 7",  "expanded": false, "controllingField": "mhp_no_of_items", "controllingValues": [">=7"],  "cloneFrom": "mhp_accessories", "replaceTarget": "mhp_acc_", "replaceWith": "c7_mhp_acc_"},
{"id": "mhp_acc_section_8",  "label": "Accessories Item - 8",  "expanded": false, "controllingField": "mhp_no_of_items", "controllingValues": [">=8"],  "cloneFrom": "mhp_accessories", "replaceTarget": "mhp_acc_", "replaceWith": "c8_mhp_acc_"},
{"id": "mhp_acc_section_9",  "label": "Accessories Item - 9",  "expanded": false, "controllingField": "mhp_no_of_items", "controllingValues": [">=9"],  "cloneFrom": "mhp_accessories", "replaceTarget": "mhp_acc_", "replaceWith": "c9_mhp_acc_"},
{"id": "mhp_acc_section_10", "label": "Accessories Item - 10", "expanded": false, "controllingField": "mhp_no_of_items", "controllingValues": [">=10"], "cloneFrom": "mhp_accessories", "replaceTarget": "mhp_acc_", "replaceWith": "c10_mhp_acc_"}
          ]
        }
      }
    }
  ]
